import{_ as r,o as i,c as l,ag as a,j as e,a as o,t as s}from"./chunks/framework.qXLDknWC.js";const y=JSON.parse('{"title":"Text Editor","description":"","frontmatter":{},"headers":[],"relativePath":"features/editor.md","filePath":"features/editor.md"}'),d={name:"features/editor.md"};function p(n,t,g,c,h,u){return i(),l("div",null,[t[25]||(t[25]=a('<h1 id="text-editor" tabindex="-1">Text Editor <a class="header-anchor" href="#text-editor" aria-label="Permalink to &quot;Text Editor&quot;">​</a></h1><p>Every text field in Character Vault uses a <strong>CodeMirror 6</strong> editor — a fast, keyboard-friendly editor with AI tools built directly into the toolbar.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>AI toolbar operations require an AI provider to be configured. If you haven&#39;t set one up, see <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>.</p></div><h2 id="ai-toolbar" tabindex="-1">AI Toolbar <a class="header-anchor" href="#ai-toolbar" aria-label="Permalink to &quot;AI Toolbar&quot;">​</a></h2><p>A fixed toolbar sits at the top of every editor. When you select text, the AI buttons become active.</p><h3 id="primary-operations" tabindex="-1">Primary Operations <a class="header-anchor" href="#primary-operations" aria-label="Permalink to &quot;Primary Operations&quot;">​</a></h3><p>These are always visible in the toolbar:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button</th><th style="text-align:left;">Operation</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;">✨ <strong>Enhance</strong></td><td style="text-align:left;">Expand</td><td style="text-align:left;">Elaborate on the selected text with more detail</td></tr><tr><td style="text-align:left;">🔄 <strong>Rephrase</strong></td><td style="text-align:left;">Rewrite</td><td style="text-align:left;">Rewrite the selection while preserving the meaning</td></tr><tr><td style="text-align:left;">💬 <strong>Custom</strong></td><td style="text-align:left;">Instruct</td><td style="text-align:left;">Type your own instruction for the AI to apply</td></tr></tbody></table><p>The <strong>Custom</strong> button opens an inline text input instead of running immediately. Type your instruction, then press <strong>Enter</strong> or click <strong>Send</strong>. Press <strong>Escape</strong> or <strong>Cancel</strong> to close it without running.</p><div class="tip custom-block"><p class="custom-block-title">Multi-line Input</p><p>All AI toolbar inputs support multi-line text. Press <strong>Shift+Enter</strong> to insert line breaks when writing detailed custom instructions.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Custom works even without a selection — you can give instructions about the whole section. For example, type &quot;add more detail&quot; to enhance the entire field at once.</p></div><h3 id="polish-operations" tabindex="-1">Polish Operations <a class="header-anchor" href="#polish-operations" aria-label="Permalink to &quot;Polish Operations&quot;">​</a></h3><p>Click <strong>▼ More</strong> to reveal a dropdown with additional operations:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button</th><th style="text-align:left;">Operation</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;">✂️ <strong>Shorten</strong></td><td style="text-align:left;">Shorten</td><td style="text-align:left;">Condense the selected text</td></tr><tr><td style="text-align:left;">📄 <strong>Lengthen</strong></td><td style="text-align:left;">Lengthen</td><td style="text-align:left;">Extend the selection with additional content</td></tr><tr><td style="text-align:left;">🎨 <strong>Vivid</strong></td><td style="text-align:left;">Vivid</td><td style="text-align:left;">Apply vivid, descriptive language</td></tr><tr><td style="text-align:left;">❤️ <strong>Emotion</strong></td><td style="text-align:left;">Emotion</td><td style="text-align:left;">Enhance emotional expression</td></tr><tr><td style="text-align:left;">🪄 <strong>Fix</strong></td><td style="text-align:left;">Grammar</td><td style="text-align:left;">Fix grammar and improve clarity</td></tr></tbody></table><h3 id="ai-operation-results-ghost-preview" tabindex="-1">AI Operation Results (Ghost Preview) <a class="header-anchor" href="#ai-operation-results-ghost-preview" aria-label="Permalink to &quot;AI Operation Results (Ghost Preview)&quot;">​</a></h3><p>AI suggestions appear <strong>in the editor</strong> as glowing ghost text at the exact place your selection was — a 1:1 preview of what Accept will write. The original selection is hidden for the preview and restored if you Reject. The top toolbar stays compact: status, optional thinking, and Accept / Reject.</p><p><strong>While the AI is working</strong></p><ul><li>Ghost text streams into place (calm, dim styling while tokens arrive).</li><li>The editor is <strong>read-only for typing</strong> so the preview stays a clean undo step — you can still scroll and move the caret to read context.</li><li>A <strong>⏹ Stop</strong> control replaces the main action buttons. Click it (or press <code>Escape</code>) to cancel.</li></ul><p><strong>When the suggestion is ready</strong></p><ul><li>Ghost text soft-pulses so you can tell it is ready to decide.</li><li>Accept / Reject appear in the slim result strip under the toolbar.</li><li>Optional performance stats (TTFT, T/S) show in that strip when available.</li></ul><p><strong>Accept or Reject</strong></p><ul><li><strong>✓ Accept</strong> (<code>Ctrl+Enter</code> / <code>⌘+Enter</code>) — Commits the ghost text into the document at the locked range. A short success toast confirms the edit. <code>Ctrl+Z</code> / <code>⌘+Z</code> undoes just that accept.</li><li><strong>✕ Reject</strong> (<code>Escape</code>) — Discards the ghost and restores your original text.</li></ul><p>The replace target is <strong>locked</strong> when the operation starts. Document saves are held until you Accept, Reject, or cancel, so unaccepted AI text is never written to storage.</p><p><strong>Selection Info</strong></p><p>When text is selected (before you run an operation), the right side of the toolbar can show a character count. If your selection is too long for the AI&#39;s context window, a warning appears and the buttons are disabled.</p><p><strong>Reasoning</strong></p><p>If the AI model produces reasoning (thinking) output, a collapsible <strong>&quot;✨ Thinking process&quot;</strong> section appears in the compact result strip. It stays <strong>collapsed by default</strong> — expand it only if you want to read the thinking.</p><h2 id="search-replace" tabindex="-1">Search &amp; Replace <a class="header-anchor" href="#search-replace" aria-label="Permalink to &quot;Search &amp; Replace&quot;">​</a></h2><p>Click the 🔍 button in the toolbar, or press <code>Ctrl+F</code> / <code>Cmd+F</code>.</p><ul><li><strong>Find</strong> — Type in the search field. Matches are highlighted in the editor.</li><li><strong>Navigate</strong> — Use the <strong>^</strong> and <strong>v</strong> buttons (or <code>Enter</code> / <code>Shift+Enter</code>) to jump between matches.</li><li><strong>Replace</strong> — Type a replacement string and use <strong>Replace</strong> (current match) or <strong>Replace All</strong>.</li><li><strong>Options</strong> — Toggle <strong>Aa</strong> (case-sensitive), <strong>ab</strong> (whole word), or <strong>.</strong>* (regular expression).</li><li><strong>Match counter</strong> — Shows the current match index and total count (e.g., &quot;3/12&quot;).</li><li><strong>Close</strong> — Press <code>Escape</code> or click <strong>×</strong>.</li></ul><p>If you have text selected when opening search, it automatically fills the search field.</p><h2 id="font-size" tabindex="-1">Font Size <a class="header-anchor" href="#font-size" aria-label="Permalink to &quot;Font Size&quot;">​</a></h2><p>Click the <strong>aA</strong> button in the toolbar to open a font size slider.</p><ul><li>Drag the slider to adjust size (6px – 32px).</li><li>The size updates on release and is remembered across sections.</li><li>The slider popup closes when you click outside it.</li></ul><h2 id="normalize-html-entities" tabindex="-1">Normalize HTML Entities <a class="header-anchor" href="#normalize-html-entities" aria-label="Permalink to &quot;Normalize HTML Entities&quot;">​</a></h2><p>Click the <strong>;&amp;</strong> button in the toolbar to normalize HTML entities into readable characters.</p><ul><li>If text is selected, only the selection is normalized.</li><li>If nothing is selected, the whole editor document is normalized.</li><li>Useful when imported cards contain text like <code>&amp;nbsp;</code>, <code>&amp;amp;</code>, <code>&amp;quot;</code>, or numeric entities.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This is available in every text editor that uses the shared CodeMirror toolbar, including standard fields, Greetings, Lorebook entry content, Creator Notes, and Extensions.</p></div><h2 id="editor-features" tabindex="-1">Editor Features <a class="header-anchor" href="#editor-features" aria-label="Permalink to &quot;Editor Features&quot;">​</a></h2>',39)),e("ul",null,[t[4]||(t[4]=e("li",null,[e("strong",null,"Spellcheck"),o(" — A custom in-editor spellchecker (Hunspell-backed) underlines misspellings and offers quick-fix suggestions. Toggle on/off and pick the language from "),e("strong",null,"Studio → Spellcheck"),o(" in Settings. The English dictionary is fetched from "),e("code",null,"/dictionary/en.{aff,dic}"),o(' on first use and cached in IndexedDB for offline access. Hover or focus over a flagged word to see suggestions plus "Ignore word" and "Add to dictionary".')],-1)),e("li",null,[t[0]||(t[0]=e("strong",null,"Name macros",-1)),t[1]||(t[1]=o(" — ",-1)),e("code",null,s(n.char),1),t[2]||(t[2]=o(" and ",-1)),e("code",null,s(n.user),1),t[3]||(t[3]=o(" are syntax-colored so they stand out while you write (case-insensitive; optional spaces inside the braces).",-1))]),t[5]||(t[5]=e("li",null,[e("strong",null,"Markdown image links"),o(" — Image syntax is highlighted; optional click-to-open is controlled under "),e("strong",null,"Settings → Studio → Editor links"),o(".")],-1))]),t[26]||(t[26]=a('<h3 id="markdown-image-links" tabindex="-1">Markdown image links <a class="header-anchor" href="#markdown-image-links" aria-label="Permalink to &quot;Markdown image links&quot;">​</a></h3><p>Markdown image syntax such as <code>![alt](https://example.com/art.png)</code> is highlighted in every shared text editor.</p><ul><li><strong>Highlight</strong> — Always on so image marks and URLs are easy to spot.</li><li><strong>Click to open</strong> — When <strong>Settings → Studio → Editor links → Open Markdown image links on click</strong> is enabled, clicking an openable <code>http</code>/<code>https</code> URL shows a leave-app safety warning, then opens the link in a new tab.</li><li><strong>Select without opening</strong> — Drag to select text; a small movement cancels the click-open action.</li><li><strong>Spellcheck-friendly</strong> — Image constructs are skipped by spellcheck so URLs and alt text don’t pile up wavy underlines.</li></ul><h3 id="name-macros" tabindex="-1">Name macros <a class="header-anchor" href="#name-macros" aria-label="Permalink to &quot;Name macros&quot;">​</a></h3>',4)),e("p",null,[e("code",null,s(n.char),1),t[6]||(t[6]=o(" and ",-1)),e("code",null,s(n.user),1),t[7]||(t[7]=o(" (and spaced forms like ",-1)),e("code",null,s(n.char),1),t[8]||(t[8]=o(") get distinct colors in the editor. Matching is case-insensitive so ",-1)),e("code",null,s(n.Char),1),t[9]||(t[9]=o(" and ",-1)),e("code",null,s(n.USER),1),t[10]||(t[10]=o(" highlight the same way.",-1))]),t[27]||(t[27]=e("h3",{id:"spellcheck",tabindex:"-1"},[o("Spellcheck "),e("a",{class:"header-anchor",href:"#spellcheck","aria-label":'Permalink to "Spellcheck"'},"​")],-1)),t[28]||(t[28]=e("p",null,"The shared editor runs a Hunspell-backed spellchecker — the same engine LibreOffice and most browsers use. It's enabled by default for every section that uses the shared toolbar: Description, Personality, Scenario, Greetings, Lorebook entry content, Creator Notes, and Extensions.",-1)),t[29]||(t[29]=e("p",null,"How it works:",-1)),e("ul",null,[t[22]||(t[22]=a("<li><strong>Underlines</strong> — Misspelled words get a wavy red underline. Hovering shows a tooltip with up to eight suggestions, plus <strong>Ignore word</strong> and <strong>Add to dictionary</strong>.</li><li><strong>Language-aware in technical sections</strong> — Creator Notes (HTML) and Extensions (JSON) automatically skip technical tokens that aren&#39;t prose: HTML element names, attribute names, attribute values, and JSON property keys (e.g. <code>full_path</code>, <code>class=&quot;sora-preview&quot;</code>). The text between tags and the JSON string <em>values</em> are still checked.</li><li><strong>Affix-aware</strong> — <code>running</code>, <code>ran</code>, and <code>runs</code> all pass without you needing to whitelist anything.</li><li><strong>Hyphenated compounds</strong> — Words like <code>well-known</code> pass when each segment is a valid dictionary word.</li>",4)),e("li",null,[t[11]||(t[11]=e("strong",null,"Smart ignores",-1)),t[12]||(t[12]=o(" — The checker automatically skips ",-1)),t[13]||(t[13]=e("code",null,"```",-1)),t[14]||(t[14]=o(" code fences, inline ",-1)),t[15]||(t[15]=e("code",null,"`code`",-1)),t[16]||(t[16]=o(" spans, ",-1)),e("code",null,s(n.macro),1),t[17]||(t[17]=o(" placeholders, Markdown image constructs, HTML tags, URLs/emails, numeric tokens, and ALL-CAPS acronyms. Add more words to your ",-1)),t[18]||(t[18]=e("strong",null,"ignored",-1)),t[19]||(t[19]=o(" or ",-1)),t[20]||(t[20]=e("strong",null,"personal dictionary",-1)),t[21]||(t[21]=o(" lists from the tooltip; they persist in your settings and apply across all cards.",-1))]),t[23]||(t[23]=e("li",null,[e("strong",null,"Debounced + viewport-only"),o(" — Only the visible portion of large lorebooks is checked, so editing stays fast.")],-1)),t[24]||(t[24]=e("li",null,[e("strong",null,"Offline"),o(" — The English Hunspell dictionary is fetched once on first use and cached in IndexedDB for subsequent visits.")],-1))]),t[30]||(t[30]=a(`<p>Toggle or switch language in <strong>Settings → Studio → Spellcheck</strong>. Currently the only bundled language is <strong>English (en-US)</strong>; additional languages can be added by dropping <code>public/dictionary/&lt;lang&gt;.aff</code> and <code>public/dictionary/&lt;lang&gt;.dic</code> into the project and listing the code in <code>src/editor/spellcheck/dictionary.ts</code>.</p><ul><li><strong>Undo/Redo</strong> — Standard <code>Ctrl+Z</code> / <code>Ctrl+Shift+Z</code> support.</li><li><strong>Line wrapping</strong> — Long lines wrap automatically.</li><li><strong>Theme sync</strong> — The editor follows the app&#39;s dark/light mode.</li><li><strong>Auto-save</strong> — Changes are saved as you type. No manual save needed.</li></ul><h2 id="section-layout" tabindex="-1">Section Layout <a class="header-anchor" href="#section-layout" aria-label="Permalink to &quot;Section Layout&quot;">​</a></h2><p>Each section tab shows a title, description, and the editor. Some sections have special layouts:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Section</th><th style="text-align:left;">Layout</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Name</strong> and <strong>Creator</strong></td><td style="text-align:left;">Simple text fields for quick edits</td></tr><tr><td style="text-align:left;"><strong>Tags</strong></td><td style="text-align:left;">Tag chips with quick add, paste, and remove controls</td></tr><tr><td style="text-align:left;"><strong>Description</strong>, <strong>Personality</strong>, <strong>Scenario</strong>, etc.</td><td style="text-align:left;">Standard single editor</td></tr><tr><td style="text-align:left;"><strong>Creator Notes</strong></td><td style="text-align:left;">Editor with a <strong>Preview CSS</strong> button — opens a sandboxed preview modal, or click again for a side-by-side split view. See <a href="/CharacterVault/docs/features/creator-notes">Creator Notes Preview</a>.</td></tr><tr><td style="text-align:left;"><strong>Greetings</strong></td><td style="text-align:left;">Special multi-greeting editor. See <a href="/CharacterVault/docs/getting-started/creating-characters">Creating &amp; Editing Characters</a>.</td></tr><tr><td style="text-align:left;"><strong>Lorebook</strong></td><td style="text-align:left;">Two-panel editor with ST fields, recursion map, search, and AI key generation. Same UI for embedded books and the <a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a>. See <a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a>.</td></tr><tr><td style="text-align:left;"><strong>Image</strong></td><td style="text-align:left;">Image upload panel (not a text editor)</td></tr><tr><td style="text-align:left;"><strong>Extensions</strong></td><td style="text-align:left;">Raw JSON editor</td></tr></tbody></table><h2 id="name-creator-and-tags" tabindex="-1">Name, Creator, and Tags <a class="header-anchor" href="#name-creator-and-tags" aria-label="Permalink to &quot;Name, Creator, and Tags&quot;">​</a></h2><p>Some short fields use simpler editors instead of the full writing toolbar:</p><ul><li><strong>Name</strong> — Type the character name directly.</li><li><strong>Creator</strong> — Type the creator name directly.</li><li><strong>Tags</strong> — Add tags with <strong>Enter</strong>, commas, or paste. Remove a tag with its <strong>x</strong> button.</li></ul><p>Tags are cleaned up as you add them. Empty tags are ignored, extra spaces are removed, and duplicates are skipped.</p><h2 id="customizing-ai-operation-prompts" tabindex="-1">Customizing AI Operation Prompts <a class="header-anchor" href="#customizing-ai-operation-prompts" aria-label="Permalink to &quot;Customizing AI Operation Prompts&quot;">​</a></h2><p>All eight toolbar operation prompts are customizable, and each one can optionally use a <strong>different AI endpoint and model</strong> than your global AI Config selection.</p><ol><li>Open <strong>Settings</strong> in the workspace header.</li><li>Go to the <strong>Prompts</strong> tab.</li><li>Expand an operation, edit the template, and (optionally) set <strong>Model for this prompt</strong>.</li><li>Click <strong>Save Settings</strong>.</li></ol><h3 id="required-placeholders" tabindex="-1">Required Placeholders <a class="header-anchor" href="#required-placeholders" aria-label="Permalink to &quot;Required Placeholders&quot;">​</a></h3><p>Prompts must include certain placeholders to work. The system validates these before saving.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Placeholder</th><th style="text-align:left;">Used In</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>\${text}</code></td><td style="text-align:left;">All operations</td><td style="text-align:left;">The selected or full editor content</td></tr><tr><td style="text-align:left;"><code>\${instruction}</code></td><td style="text-align:left;">Custom only</td><td style="text-align:left;">The custom instruction text</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">What is a placeholder?</p><p>A <strong>placeholder</strong> is a special token that gets replaced with actual content before the prompt is sent to the AI provider.</p><p><strong>Example:</strong> In the template <code>Enhance the following text: \${text}</code>, the placeholder is replaced with your selection when you click <strong>Enhance</strong>.</p></div><p><strong>Primary prompts</strong> (Enhance, Rephrase) need <code>\${text}</code>. <strong>Polish prompts</strong> (Shorten, Lengthen, Vivid, Emotion, Fix) also need <code>\${text}</code>.</p><p><strong>Custom</strong> is special — it needs both <code>\${instruction}</code> and <code>\${text}</code>. When the editor has content, your template is used. When it&#39;s empty, the system swaps in a generation template instead.</p><details class="details custom-block"><summary>How Custom works with empty editors</summary><p>When the editor is empty, the system swaps the entire prompt template for a generation-oriented one. This lets the Custom button work both as a text modifier <strong>and</strong> a text generator.</p><p><strong>Default Custom template (with editor content):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please apply the following instruction to the text below:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Instruction: \${instruction}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Text:</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span>\${text}</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Provide only the modified text without any additional commentary.</span></span></code></pre></div><p><strong>When the editor is empty</strong>, the template is replaced entirely:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please generate text based on the following instruction:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Instruction: &lt;your instruction&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Provide only the generated text without any additional commentary.</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Not yet customizable</p><p>The empty-editor prompt is currently hardcoded and cannot be edited in the Prompts tab. Customization for this prompt is planned for a future release.</p></div></details><blockquote><p>Don&#39;t worry if you forget — you can&#39;t save a prompt without the required placeholders. An error message will remind you to include them.</p></blockquote><h3 id="per-operation-model-routing" tabindex="-1">Per-operation model routing <a class="header-anchor" href="#per-operation-model-routing" aria-label="Permalink to &quot;Per-operation model routing&quot;">​</a></h3><p>By default every toolbar op uses the model from <strong>Settings → AI Config</strong>. You can override that per prompt:</p><ol><li>Expand a prompt (e.g. <strong>Fix</strong>).</li><li>Under <strong>Model for this prompt</strong>, change <strong>Endpoint</strong> from <strong>Default (AI Config)</strong> to Nano-GPT, OpenRouter, Minimax, LM Studio, or a custom URL that already has a key on AI Config.</li><li>Choose a model from the sheet, <strong>Fetch models</strong> for that endpoint, or type a model ID.</li><li>Save settings.</li></ol><p>Collapsed headers show <code>→ model-id</code> when a mapping is active.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Operation</th><th style="text-align:left;">Mapping key</th></tr></thead><tbody><tr><td style="text-align:left;">Enhance</td><td style="text-align:left;">expand</td></tr><tr><td style="text-align:left;">Rephrase</td><td style="text-align:left;">rewrite</td></tr><tr><td style="text-align:left;">Custom</td><td style="text-align:left;">instruct (also used by lorebook AI key generation)</td></tr><tr><td style="text-align:left;">Shorten / Lengthen / Vivid / Emotion / Fix</td><td style="text-align:left;">matching polish op</td></tr></tbody></table><p><strong>Not overridden by these mappings:</strong> Orion chat and AI Creation Studio always use the global AI Config model. Streaming, reasoning, and sampler settings stay global.</p><p>Full setup notes: <a href="/CharacterVault/docs/configuration/ai-setup#prompts-tab">AI Setup → Prompts Tab</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook editor</a></li><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a></li><li><a href="/CharacterVault/docs/features/creator-notes">Creator Notes preview</a></li><li><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant — Orion</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure AI provider</a></li><li><a href="/CharacterVault/docs/configuration/section-layout">Customize section tab layout</a></li></ul>`,29))])}const f=r(d,[["render",p]]);export{y as __pageData,f as default};
